#include "elit21/shopify/webhooks/InventoryWebhookHandler.h"
namespace elit21::shopify::webhooks {InventoryWebhookHandler::InventoryWebhookHandler():platform::BusinessComponent("InventoryWebhookHandler","Persistent Shopify webhook domain handler",platform::BusinessComponentSpec{"shopify","handle_webhook",{},true,false,16U*1024U*1024U}){}InventoryWebhookHandler::InventoryWebhookHandler(Database&database):InventoryWebhookHandler(){database_=&database;}Result<void>InventoryWebhookHandler::handle(const ShopifyWebhook&event){if(!database_)return Result<void>::failure("InventoryWebhookHandler is not bound to Database");return persistWebhookTask(*database_,event,{ShopifyWebhookTopic::inventory_levels_update});}platform::OperationResult InventoryWebhookHandler::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["database_bound"]=database_?1.0:0.0;r.attributes["handler"]="InventoryWebhookHandler";return r;}}
